criteria.expect:
(() => {
  // ★ 2026-10-26：**用结构（node.path / semantic.files.path），不用散文（node.description）**。
  //   病史：原判据的 `paths` 是 design-check 从 node.description 推的 —— 扫描建的节点恰好
  //   description === path，所以一直"看起来对"；而手写的 file 节点 description 写的是职责句
  //   ⇒ 被判成"path 不存在"（实测：docs/VISION.md 入册 + semantic.files 也有它，D1 仍红）。
  const norm = (s) => String(s ?? '').replace(/\\/g, '/').replace(/^\.\//, '').trim();
  const need = new Set();
  for (const n of nodes) for (const e of (n.decision?.expectations ?? [])) {
    const p = norm(e.path);
    if (p) need.add(p);
  }
  const have = new Set();
  for (const n of nodes) { const p = norm(n.path); if (p) have.add(p); }
  for (const f of (dsl.semantic?.files ?? [])) { const p = norm(f.path); if (p) have.add(p); }
  const missing = [...need].filter((p) => !have.has(p));
  return missing.length === 0;
})()

(() => {
    // ★ 2026-10-31：口径写清，**不靠 `p &&` 静默过滤**。
    //   · 「每个节点有 path」的真判据 = **所有 type='file' 节点都必须有 path**（分母不看 SCOPE）；
    //     豁免（写进 rule）：type='module'（目录节点）与 type='doc'（册根 / 无单一文件的文档节点）—— 它们本来就没有 path。
    //   · 职责（summary + acceptance）仍只对 SCOPE 范围内要求：渲染/画图那一片不要求。
    const SCOPE = ['src/application/design/dsl_ops/', 'src/application/patrol/', 'src/domain/'];
    const norm = (s) => String(s ?? '').replace(/\\/g, '/').replace(/^\.\//, '');
    // ① path 完整性：分母 = 全部 type='file' 节点（不看 SCOPE）
    const fileNodes = nodes.filter((n) => n.type === 'file');
    const noPath = fileNodes.filter((n) => !norm(n.path));
    // ② 职责完整：分母 = SCOPE 内节点
    const inScope = nodes.filter((n) => SCOPE.some((s) => norm(n.path).startsWith(s)));
    const bad = inScope.filter((n) => {
      const d = n.decision;
      return !d || !String(d.summary ?? '').trim() || !String(d.acceptance ?? '').trim();
    });
    return noPath.length === 0 && bad.length === 0;
  })()

(() => {
  // ★ 2026-10-26：不再抄一份白名单 —— 直接用**注入的权威** KINDS（= domain/expectation.ts#EXPECTATION_KINDS）。
  //   抄一份的后果实测过两次：漏 source-has 时红一次、漏 behavior-cases 时又红一次。
  const bad = [];
  for (const n of nodes) for (const e of (n.decision?.expectations ?? [])) {
    if (!KINDS.includes(e.kind)) bad.push(n.id + ':' + String(e.kind));
  }
  return bad.length === 0;
})()

(() => {
      const t = dsl.task_plan?.state_machine?.transitions ?? [];
      return t.every((x) => x && x.state && typeof x.state.kind === 'string' && x.state.kind.trim());
    })()

(() => {
    // ★ ready 的每条迁移都要有 executor（指向 task_ops.ts 里的真实函数）
    const t = dsl.task_plan?.state_machine?.transitions ?? [];
    return t.every((x) => (x.state?.kind !== 'ready') || (typeof x.executor === 'string' && x.executor.trim().length > 0));
  })()

(() => {
      const b = dsl.task_plan?.assertion_baseline_2026_10_17;
      if (!b) return false;
      return (b.machine ?? 0) + (b.review ?? 0) + (b.unjudged ?? 0) === b.total;
    })()

(() => {
    // ★ unjudged 的每条都要带欠账号
    const ups = dsl.task_plan?.assertion_baseline_2026_10_17?.unjudged_paths ?? [];
    return ups.every((p) => p && typeof p === 'object' && typeof p.path === 'string' && typeof p.debt === 'string' && p.debt.trim().length > 0);
  })()

(() => {
  // ★ D6：所有 call-exists 期望都成立。
  //   ★★ 2026-10-19 修假绿：原来只判 "checked>=1 && failed===0" —— 而 9 条全是 unsupported（索引过期）
  //      ⇒ failed=0 ⇒ 绿。⇒ 现在必须【unsupported === 0】（判不了不算通过）。
  if (!callReport) return false;
  if (callReport.error) return false;
  return callReport.checked >= 1 && callReport.failed === 0 && callReport.unsupported === 0;
})()
